74	    /** Dedicated audit logger; each successful owner create emits one line here. */
75	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
76	
77	    /** Dedicated notification logger; each successful owner create enqueues a welcome line here. */
78	    private static final Logger NOTIFY = LoggerFactory.getLogger("NOTIFY");
79	
80	    /**
81	     * Monotonically increasing sequence stamped onto each structured {@code OWNER_CREATED}
82	     * event, shared across every controller instance so the {@code seq} strictly increases
83	     * across all owner creates for the life of the process.
84	     */
85	    private static final java.util.concurrent.atomic.AtomicLong AUDIT_EVENT_SEQ =
86	        new java.util.concurrent.atomic.AtomicLong();
87	
88	    /**
89	     * The header carrying an idempotency key for owner creation. When a create repeats with a key
90	     * already seen, the originally created owner is returned with 200 instead of creating a duplicate.
91	     */
92	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
93	
94	    /**
95	     * Remembers, per seen idempotency key, the id of the owner that create originally produced, so a
96	     * repeat of the same request returns that owner rather than creating a duplicate.
97	     */
98	    private final Map<String, Integer> idempotentCreates = new java.util.concurrent.ConcurrentHashMap<>();
99	
