118	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
119	    @Override
120	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
121	        Collection<Owner> owners;
122	        if (lastName != null) {
123	            owners = this.clinicService.findOwnerByLastName(lastName);
124	        } else {
125	            owners = this.clinicService.findAllOwners();
126	        }
127	        if (owners.isEmpty()) {
128	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
129	        }
130	        Map<String, Integer> householdSizes = householdSizes();
131	        List<OwnerDto> ownerDtos = new java.util.ArrayList<>();
132	        for (Owner owner : owners) {
133	            OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
134	            applyMembership(ownerDto, owner, householdSizes);
135	            ownerDtos.add(ownerDto);
136	        }
137	        return new ResponseEntity<>(ownerDtos, HttpStatus.OK);
138	    }
