155	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
156	    @Override
157	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
158	        HttpHeaders headers = new HttpHeaders();
159	        String idempotencyKey = currentIdempotencyKey();
160	        if (idempotencyKey != null) {
161	            Integer existingId = idempotentCreates.get(idempotencyKey);
162	            if (existingId != null) {
163	                Owner existing = this.clinicService.findOwnerById(existingId);
164	                if (existing != null) {
165	                    OwnerDto existingDto = ownerMapper.toOwnerDto(existing);
166	                    applyMembership(existingDto, existing);
167	                    existingDto.setBulkSignupWarning(isBulkSignupDay());
168	                    existingDto.setCapacityWarning(isApproachingCapacity(existing.getCity()));
169	                    existingDto.setRiskFlag(isRiskFlag(existing));
170	                    return new ResponseEntity<>(existingDto, HttpStatus.OK);
171	                }
172	            }
173	        }
174	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
175	        String address = applyAddress(owner, ownerFieldsDto);
176	        if (address.isEmpty()) {
177	            throw new BadRequestException("The owner's address is missing or could not be resolved to a valid address");
178	        }
179	        owner.setAddress(address);
180	        String telephone = toE164(owner.getTelephone());
181	        if (telephone == null) {
182	            throw new BadRequestException("The owner's telephone number is not a valid phone number");
183	        }
184	        owner.setTelephone(telephone);
185	        if (owner.getEmail() != null) {
186	            String email = normalizeEmail(owner.getEmail());
187	            if (email == null) {
188	                throw new BadRequestException("The owner's email address is invalid or uses a disallowed domain");
189	            }
190	            owner.setEmail(email);
191	        }
192	        if (owner.getPostcode() != null && !isValidPostcode(owner.getPostcode(), owner.getCity())) {
193	            throw new BadRequestException("The owner's postcode is not valid for the given city");
194	        }
195	        LocalDate effectiveRegistrationDate = owner.getRegistrationDate();
196	        if (effectiveRegistrationDate == null) {
197	            effectiveRegistrationDate = LocalDate.now();
198	        }
199	        else if (effectiveRegistrationDate.isAfter(LocalDate.now())) {
200	            throw new BadRequestException("The owner's registration date cannot be in the future");
201	        }
202	        LocalDate registrationDate = toBusinessDay(effectiveRegistrationDate);
203	        owner.setRegistrationDate(registrationDate);
204	        if (countOwnersInCity(owner.getCity()) >= MAX_OWNERS_PER_CITY) {
205	            throw new ConflictException("The maximum number of owners for this city has been reached");
206	        }
207	        if (countOwnersRegisteredOn(registrationDate) >= MAX_OWNERS_PER_DAY) {
208	            throw new RateLimitExceededException("The maximum number of owner registrations for this day has been reached");
209	        }
210	        // The householdId is deterministic: the first twelve hex characters of SHA-256 over
211	        // '<normalizedLastName>|<postcode>'. Owners sharing a last name and postcode therefore
212	        // share the household automatically. An owner without a postcode has no household.
213	        boolean declaredHouseholdMember = false;
214	        if (owner.getPostcode() != null) {
215	            String householdId = householdId(householdKey(owner.getLastName()), owner.getPostcode());
216	            owner.setHouseholdId(householdId);
217	            // A second owner sharing a household (same lastName + postcode) but with a distinct
218	            // identity is a legitimate additional household member — true duplicates are still
219	            // caught by the identityKey check below. 'sharesHousehold' opts such an owner in as a
220	            // declared member so it is not additionally flagged as a possible duplicate.
221	            boolean householdOccupied = false;
222	            for (Owner existing : this.clinicService.findAllOwners()) {
223	                if (existing.isDeleted()) {
224	                    continue;
225	                }
226	                if (householdId.equals(computeHouseholdId(existing))) {
227	                    householdOccupied = true;
228	                    break;
229	                }
230	            }
231	            if (householdOccupied && Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
232	                declaredHouseholdMember = true;
233	            }
234	        }
235	        // Consolidated duplicate detection: reject only when the whole identityKey
236	        // (SHA-256 over normalizedTelephone | lowerEmail | soundex(lastName)) matches an
237	        // existing owner's. This is the single duplicate check; owners sharing a household
238	        // (same last name and postcode) but with different telephones produce different keys
239	        // and are no longer rejected here — they surface as soft matches below.
240	        String identityKey = OwnerIdentity.identityKey(owner.getTelephone(), owner.getEmail(), owner.getLastName());
241	        for (Owner existing : this.clinicService.findAllOwners()) {
242	            if (existing.isDeleted()) {
243	                continue;
244	            }
245	            if (identityKey.equals(OwnerIdentity.identityKey(toE164(existing.getTelephone()),
246	                existing.getEmail(), existing.getLastName()))) {
247	                throw new ConflictException("An owner with the same identity already exists");
248	            }
249	        }
250	        // Soft-match: the owner is not a hard (identityKey) duplicate, but if it shares an
251	        // existing owner's last name and postcode while having a different normalized
252	        // telephone it is still created and flagged as a possible duplicate of that owner. A
253	        // declared household member, however, is not a suspected duplicate, so it is never flagged.
254	        if (declaredHouseholdMember) {
255	            owner.setPossibleDuplicate(false);
256	        }
257	        else {
258	            applyPossibleDuplicate(owner);
259	        }
260	        owner.setMemberId(deduplicatedMemberId(memberId(
261	            owner.getPostcode(), owner.getTelephone(), owner.getLastName(), owner.getRegistrationDate())));
262	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
263	        this.clinicService.saveOwner(owner);
264	        if (idempotencyKey != null) {
265	            idempotentCreates.put(idempotencyKey, owner.getId());
266	        }
267	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
268	        Map<String, Integer> householdSizes = householdSizes();
269	        applyMembership(ownerDto, owner, householdSizes);
270	        capMembershipLevelToHousehold(ownerDto, owner, householdSizes);
271	        applyOwnerSegment(ownerDto);
272	        AUDIT.info("owner created: id={} memberId={} registrationDate={} membershipLevel={}",
273	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(),
274	            ownerDto.getMembershipLevel());
275	        emitOwnerCreatedEvent(owner.getId(), primaryIdentifier(owner), ownerDto.getMembershipLevel(),
276	            ownerDto.getOwnerSegment());
277	        NOTIFY.info("welcome: ownerId={} memberId={}", owner.getId(), owner.getMemberId());
278	        ownerDto.setBulkSignupWarning(isBulkSignupDay());
279	        ownerDto.setCapacityWarning(isApproachingCapacity(owner.getCity()));
280	        ownerDto.setRiskFlag(isRiskFlag(owner));
281	        headers.setLocation(UriComponentsBuilder.newInstance()
282	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
283	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
284	    }
285	
286	    /**
287	     * The owner's current primary identifier, as carried by the structured {@code OWNER_CREATED}
288	     * event. This is the owner's unified {@link Owner#getMemberId() memberId}.
289	     *
290	     * @param owner the newly created, saved owner
291	     * @return the owner's current primary identifier
292	     */
293	    private static String primaryIdentifier(Owner owner) {
294	        return owner.getMemberId();
295	    }
296	
297	    /**
298	     * Emits the immutable, structured {@code OWNER_CREATED} audit event via the {@code AUDIT}
299	     * logger, in addition to the human-readable audit line. The event is a schema-version-2 JSON
300	     * object {@code {schemaVersion:2, seq, ownerId, memberId, membershipLevel, ownerSegment,
301	     * event:'OWNER_CREATED'}} where {@code seq} is a process-wide monotonically increasing integer
302	     * across creates, the {@code memberId} slot carries the owner's {@link #primaryIdentifier
303	     * current primary identifier} (the version-2 memberId) and {@code ownerSegment} is the owner
304	     * segment recomputed from that version-2 identity.
305	     *
306	     * @param ownerId         the newly created owner's id
307	     * @param primaryId       the owner's current primary identifier (the version-2 memberId)
308	     * @param membershipLevel the owner's resolved membership level
309	     * @param ownerSegment    the owner segment recomputed from the version-2 identity
310	     */
311	    private static void emitOwnerCreatedEvent(int ownerId, String primaryId, int membershipLevel,
312	        String ownerSegment) {
313	        long seq = AUDIT_EVENT_SEQ.incrementAndGet();
314	        AUDIT.info("{\"schemaVersion\":2,\"seq\":{},\"ownerId\":{},\"memberId\":\"{}\","
315	            + "\"membershipLevel\":{},\"ownerSegment\":\"{}\",\"event\":\"OWNER_CREATED\"}",
316	            seq, ownerId, primaryId, membershipLevel, ownerSegment);
317	    }
318	
319	    /**
320	     * Reads the {@code Idempotency-Key} header of the request currently being handled, used to make
321	     * owner creation idempotent. Returns the trimmed key when present and non-blank, otherwise
322	     * {@code null} (including when there is no active servlet request), so a missing or blank key
323	     * simply means "no idempotency" and the create proceeds normally.
324	     *
325	     * @return the current request's idempotency key, or {@code null} when none is supplied
326	     */
327	    private static String currentIdempotencyKey() {
328	        RequestAttributes attributes = RequestContextHolder.getRequestAttributes();
329	        if (!(attributes instanceof ServletRequestAttributes servletAttributes)) {
330	            return null;
331	        }
332	        String key = servletAttributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
333	        if (key == null || key.isBlank()) {
334	            return null;
335	        }
336	        return key.trim();
337	    }
