340	    @Override
341	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
342	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
343	        if (currentOwner == null) {
344	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
345	        }
346	        currentOwner.setAddress(ownerFieldsDto.getAddress());
347	        currentOwner.setCity(ownerFieldsDto.getCity());
348	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
349	        currentOwner.setLastName(ownerFieldsDto.getLastName());
350	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
351	        this.clinicService.saveOwner(currentOwner);
352	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
353	    }
