355	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
356	    @Transactional
357	    @Override
358	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
359	        Owner owner = this.clinicService.findOwnerById(ownerId);
360	        if (owner == null) {
361	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
362	        }
363	        // Soft delete: the row is retained and flagged deleted rather than removed, so the
364	        // owner is still readable via GET but is ignored by the create duplicate/identity checks.
365	        owner.setDeleted(true);
366	        this.clinicService.saveOwner(owner);
367	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
368	    }
