435	    /**
436	     * The maximum number of owners permitted per city. Owner creation is rejected once the
437	     * owner's city already contains this many owners.
438	     */
439	    private static final int MAX_OWNERS_PER_CITY = 50;
440	
441	    /**
442	     * Counts how many existing owners live in the given city, compared case-insensitively.
443	     * This is evaluated before the new owner is persisted, so the owner being created is not
444	     * included in the count.
445	     *
446	     * @param city the new owner's city
447	     * @return the number of existing owners in that city
448	     */
449	    private int countOwnersInCity(String city) {
450	        int count = 0;
451	        for (Owner existing : this.clinicService.findAllOwners()) {
452	            if (city.equalsIgnoreCase(existing.getCity())) {
453	                count++;
454	            }
455	        }
456	        return count;
457	    }
458	
459	    /**
460	     * The number of owners in a city at or above which a capacity warning is raised. Once the
461	     * owner's city holds at least this many owners (but is still below {@link #MAX_OWNERS_PER_CITY},
462	     * the hard limit), the city is approaching capacity and {@code capacityWarning} is reported as
463	     * {@code true} in the owner response.
464	     */
465	    private static final int CAPACITY_WARNING_THRESHOLD = 40;
466	
467	    /**
468	     * Reports whether the given city is approaching the per-city capacity limit, i.e. whether it
469	     * already holds between {@link #CAPACITY_WARNING_THRESHOLD} (40) and
470	     * {@link #MAX_OWNERS_PER_CITY} minus one (49) owners inclusive. At the hard limit of 50 the
471	     * create is rejected outright, so a full city never warns.
472	     *
473	     * @param city the owner's city
474	     * @return {@code true} when the city holds 40-49 owners, otherwise {@code false}
475	     */
476	    private boolean isApproachingCapacity(String city) {
477	        int count = countOwnersInCity(city);
478	        return count >= CAPACITY_WARNING_THRESHOLD && count < MAX_OWNERS_PER_CITY;
479	    }
480	
481	    /**
482	     * The maximum number of owners that may be created in a single business day. Owner
483	     * creation is rejected once this many owners already fall on the new owner's adjusted
484	     * business day {@code registrationDate}.
485	     */
486	    private static final int MAX_OWNERS_PER_DAY = 100;
487	
488	    /**
489	     * The fixed list of public holidays that the business-day roll skips over. A date that
490	     * lands on one of these is rolled forward to the next non-holiday business day.
491	     */
492	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
493	        LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"),
494	        LocalDate.parse("2026-04-25"), LocalDate.parse("2026-12-25"),
495	        LocalDate.parse("2026-12-28"));
496	
497	    /**
498	     * Rolls a date forward to the next business day: a Saturday, Sunday or listed public
499	     * holiday is moved forward one day at a time until a non-holiday weekday is reached,
500	     * while a date that is already a non-holiday weekday is returned unchanged.
501	     *
502	     * @param date the date to adjust
503	     * @return the same date if it is a non-holiday weekday, otherwise the next such day
504	     */
505	    private LocalDate toBusinessDay(LocalDate date) {
506	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY
507	                || PUBLIC_HOLIDAYS.contains(date)) {
508	            date = date.plusDays(1);
509	        }
510	        return date;
511	    }
512	
513	    /**
514	     * Counts how many existing owners fall on the given business day, i.e. whose {@code
515	     * registrationDate} rolls forward to the same business day. This is evaluated before the
516	     * new owner is persisted, so the owner being created is not included in the count.
517	     *
518	     * @param businessDay the adjusted business day to count against
519	     * @return the number of existing owners registered on that business day
520	     */
521	    private int countOwnersRegisteredOn(LocalDate businessDay) {
522	        int count = 0;
523	        for (Owner existing : this.clinicService.findAllOwners()) {
524	            LocalDate existingDate = existing.getRegistrationDate();
525	            if (existingDate != null && businessDay.equals(toBusinessDay(existingDate))) {
526	                count++;
527	            }
528	        }
529	        return count;
530	    }
