550	    /**
551	     * Builds the version-2 unified member id for a newly created owner, formatted
552	     * {@code '<REGION><FY><HASH8><CHK>'} where {@code REGION} is the version-2 region code — the
553	     * fixed {@code 'V2'} tag followed by the canonical region
554	     * {@link OwnerLocality#forPostcodeOrUnknown derived from the postcode} (or
555	     * {@code "V2UNKNOWN"} when the postcode resolves no region), {@code FY} is the last two
556	     * digits of the fiscal year of the business-day-adjusted registration date (fiscal year
557	     * starts 1 July, named by the year it ends in), {@code HASH8} is the first eight
558	     * upper-case hex characters of the SHA-256 digest of
559	     * {@code 'V2' + normalizedTelephone + lastName}, and {@code CHK} is a single Luhn
560	     * check digit computed over the digits of {@code '<REGION><FY><HASH8>'}. Mixing the
561	     * {@code 'V2'} tag into both the region code and the hash means no version-1 member id
562	     * recurs. The id carries no sequence number, so it is stable for a given telephone, last
563	     * name and fiscal year rather than dependent on creation order.
564	     *
565	     * @param postcode            the owner's postcode (may be {@code null})
566	     * @param normalizedTelephone the owner's normalized E.164 telephone
567	     * @param lastName            the owner's last name
568	     * @param registrationDate    the owner's business-day-adjusted registration date
569	     * @return the assigned member id (e.g. {@code 'V2NSW271A2B3C4D5'})
570	     */
571	    private static String memberId(String postcode, String normalizedTelephone, String lastName,
572	        LocalDate registrationDate) {
573	        // Version-2 region code: the fixed 'V2' tag mixed in front of the plain canonical region,
574	        // so the region code carried inside the identifier differs from every version-1 value. The
575	        // plain region still feeds the user-facing locality/timezone/segment, which never see 'V2'.
576	        String region = OwnerIdentity.VERSION_TAG
577	            + org.springframework.samples.petclinic.mapper.OwnerLocality.forPostcodeOrUnknown(postcode);
578	        int fiscalYear = org.springframework.samples.petclinic.mapper.FiscalYear.yearValue(registrationDate);
579	        String fy = String.format("%02d", Math.floorMod(fiscalYear, 100));
580	        String base = region + fy + sha256Hex8(OwnerIdentity.VERSION_TAG + normalizedTelephone + lastName);
581	        int chk = org.springframework.samples.petclinic.mapper.OwnerLocality.luhn(base);
582	        return base + chk;
583	    }
