585	    /**
586	     * De-duplicates a freshly computed {@code base} member id against the ids already
587	     * assigned to existing owners. When {@code base} is free it is returned unchanged;
588	     * otherwise {@code '-<n>'} is appended with the smallest {@code n} of two or more that
589	     * yields an id no existing owner holds.
590	     *
591	     * @param base the computed {@code '<REGION><FY><HASH8><CHK>'} member id
592	     * @return {@code base}, or {@code base + "-<n>"} de-duplicated to be unique
593	     */
594	    private String deduplicatedMemberId(String base) {
595	        Set<String> existing = new HashSet<>();
596	        for (Owner owner : this.clinicService.findAllOwners()) {
597	            if (owner.getMemberId() != null) {
598	                existing.add(owner.getMemberId());
599	            }
600	        }
601	        if (!existing.contains(base)) {
602	            return base;
603	        }
604	        int n = 2;
605	        while (existing.contains(base + "-" + n)) {
606	            n++;
607	        }
608	        return base + "-" + n;
609	    }
