611	    /**
612	     * Returns the first eight upper-case hex characters of the SHA-256 digest of the UTF-8
613	     * bytes of {@code source} — the {@code HASH8} component of an owner's member id.
614	     *
615	     * @param source the string to hash
616	     * @return the first eight upper-case hex characters of {@code SHA-256(source)}
617	     */
618	    private static String sha256Hex8(String source) {
619	        try {
620	            byte[] digest = MessageDigest.getInstance("SHA-256")
621	                .digest(source.getBytes(StandardCharsets.UTF_8));
622	            StringBuilder hex = new StringBuilder(digest.length * 2);
623	            for (byte b : digest) {
624	                hex.append(String.format("%02x", b));
625	            }
626	            return hex.substring(0, 8).toUpperCase();
627	        } catch (NoSuchAlgorithmException e) {
628	            throw new IllegalStateException("SHA-256 not available", e);
629	        }
630	    }
