652	    /**
653	     * Canonical expansions applied to common street-type abbreviations during address
654	     * normalization. Keys and values are upper-cased so the lookup runs after the address
655	     * has itself been upper-cased.
656	     */
657	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
658	        "ST", "STREET",
659	        "RD", "ROAD",
660	        "AVE", "AVENUE");
661	
662	    /**
663	     * Normalizes an owner address for creation. Leading and trailing whitespace is trimmed,
664	     * every run of internal whitespace is collapsed to a single space, the result is
665	     * upper-cased and common street-type abbreviations are expanded ({@code ST -> STREET},
666	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). An abbreviation is recognized as a whole
667	     * token, optionally carrying a single trailing full stop (so both {@code 'St'} and
668	     * {@code 'St.'} become {@code 'STREET'}). The normalized value is what gets stored,
669	     * returned and compared for household duplicates; an address that is blank once
670	     * normalized fails the required-field check.
671	     *
672	     * @param address the raw address value supplied by the client
673	     * @return the normalized address (empty string when {@code address} is null or blank)
674	     */
675	    /**
676	     * Normalizes the address an owner supplies, preferring the structured form, and stores the
677	     * normalized structured lines on the owner. When a non-blank {@code addressLine1} is present
678	     * the structured fields are used: {@code addressLine1} (and {@code addressLine2}, when
679	     * present) are {@link #normalizeAddress normalized} and set on the owner, and the composed
680	     * address returned is the normalized {@code addressLine1} with a single space and the
681	     * normalized {@code addressLine2} appended when {@code addressLine2} is present. Otherwise
682	     * the flat {@code address} is normalized and returned, and the structured lines are left
683	     * unset. The returned value becomes the owner's stored {@code address}, read by everything
684	     * downstream (household hash, postcode validation and locality); an owner that supplies
685	     * neither form yields an empty string, failing the required-address check.
686	     *
687	     * @param owner          the owner being created, whose structured address lines are set here
688	     * @param ownerFieldsDto the submitted owner fields
689	     * @return the composed, normalized address (empty string when no address form is supplied)
690	     */
691	    private static String applyAddress(Owner owner, OwnerFieldsDto ownerFieldsDto) {
692	        String addressLine1 = ownerFieldsDto.getAddressLine1();
693	        if (addressLine1 != null && !addressLine1.isBlank()) {
694	            String normalizedLine1 = normalizeAddress(addressLine1);
695	            owner.setAddressLine1(normalizedLine1);
696	            String addressLine2 = ownerFieldsDto.getAddressLine2();
697	            if (addressLine2 != null && !addressLine2.isBlank()) {
698	                String normalizedLine2 = normalizeAddress(addressLine2);
699	                owner.setAddressLine2(normalizedLine2);
700	                return normalizedLine1 + " " + normalizedLine2;
701	            }
702	            owner.setAddressLine2(null);
703	            return normalizedLine1;
704	        }
705	        owner.setAddressLine1(null);
706	        owner.setAddressLine2(null);
707	        return normalizeAddress(ownerFieldsDto.getAddress());
708	    }
709	
710	    private static String normalizeAddress(String address) {
711	        if (address == null) {
712	            return "";
713	        }
714	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase();
715	        if (collapsed.isEmpty()) {
716	            return "";
717	        }
718	        StringBuilder normalized = new StringBuilder(collapsed.length());
719	        for (String token : collapsed.split(" ")) {
720	            String core = token.endsWith(".") ? token.substring(0, token.length() - 1) : token;
721	            String expanded = ADDRESS_ABBREVIATIONS.get(core);
722	            if (normalized.length() > 0) {
723	                normalized.append(' ');
724	            }
725	            normalized.append(expanded != null ? expanded : token);
726	        }
727	        return normalized.toString();
728	    }
