730	    /**
731	     * Normalizes a last name or address for household-duplicate comparison: leading and
732	     * trailing whitespace is trimmed, every run of internal whitespace is collapsed to a
733	     * single space and the result is lower-cased. Two owners are considered to share a
734	     * household when both their last names and addresses produce the same key.
735	     *
736	     * @param value the raw last name or address value
737	     * @return the normalized comparison key (empty string when {@code value} is null)
738	     */
739	    private static String householdKey(String value) {
740	        if (value == null) {
741	            return "";
742	        }
743	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
744	    }
