746	    /**
747	     * Derives the stable shared household identifier for the given normalized last name key
748	     * and postcode. The identifier is deterministic — the same household (same
749	     * {@link #householdKey normalized} last name and postcode) always maps to the same
750	     * value — so every owner in a household is assigned an identical id. It is the
751	     * upper-cased first twelve hex characters of the SHA-256 digest of {@code
752	     * 'V2|<lastNameKey>|<postcode>'}, the leading {@code 'V2'} being the fixed version-2 tag
753	     * that distinguishes it from the version-1 household id.
754	     *
755	     * @param lastNameKey the normalized last name key
756	     * @param postcode    the owner's postcode
757	     * @return the shared household identifier
758	     */
759	    private static String householdId(String lastNameKey, String postcode) {
760	        String source = OwnerIdentity.VERSION_TAG + "|" + lastNameKey + "|" + postcode;
761	        try {
762	            byte[] digest = MessageDigest.getInstance("SHA-256")
763	                .digest(source.getBytes(StandardCharsets.UTF_8));
764	            StringBuilder hex = new StringBuilder(digest.length * 2);
765	            for (byte b : digest) {
766	                hex.append(String.format("%02x", b));
767	            }
768	            return hex.substring(0, 12).toUpperCase();
769	        } catch (NoSuchAlgorithmException e) {
770	            throw new IllegalStateException("SHA-256 not available", e);
771	        }
772	    }
