774	    /**
775	     * Computes the deterministic {@link #householdId household id} an existing owner belongs to,
776	     * derived from its {@link #householdKey normalized} last name and its postcode. Returns
777	     * {@code null} when the owner has no postcode (such an owner has no household), so it never
778	     * collides with a computed household id.
779	     *
780	     * @param owner the existing owner
781	     * @return the owner's household id, or {@code null} when it has no postcode
782	     */
783	    private static String computeHouseholdId(Owner owner) {
784	        if (owner.getPostcode() == null) {
