803	    /**
804	     * Populates an owner's {@code membershipPoints} and {@code membershipLevel} on the given
805	     * dto using a pre-computed map of household id to member count.
806	     *
807	     * @param ownerDto       the dto to populate
808	     * @param owner          the owner being mapped
809	     * @param householdSizes household id to member count, as returned by {@link #householdSizes()}
810	     */
811	    private void applyMembership(OwnerDto ownerDto, Owner owner, Map<String, Integer> householdSizes) {
812	        int householdSize = owner.getHouseholdId() == null ? 1
813	            : householdSizes.getOrDefault(owner.getHouseholdId(), 1);
814	        int points = MembershipPoints.points(owner, householdSize);
815	        ownerDto.setMembershipPoints(points);
816	        ownerDto.setMembershipLevel(MembershipPoints.level(points));
817	        applyOwnerSegment(ownerDto);
