820	    /**
821	     * Populates an owner's {@code ownerSegment} on the given dto from its already-applied
822	     * {@code membershipLevel} and mapped {@code locality}. Call this whenever the membership
823	     * level changes (e.g. after {@link #capMembershipLevelToHousehold}) so the segment stays
824	     * consistent with the level.
825	     *
826	     * @param ownerDto the dto whose membershipLevel and locality are already populated
827	     */
828	    private void applyOwnerSegment(OwnerDto ownerDto) {
829	        Integer membershipLevel = ownerDto.getMembershipLevel();
830	        int level = membershipLevel == null ? 1 : membershipLevel;
831	        ownerDto.setOwnerSegment(org.springframework.samples.petclinic.mapper.OwnerSegment.segment(
832	            level, ownerDto.getLocality()));
833	    }
