835	    /**
836	     * Caps a newly created owner's {@code membershipLevel} at one above the highest
837	     * {@code membershipLevel} among the other current members of its household, writing the
838	     * capped value back onto the dto and returning it. A member's current level is scored the
839	     * same way as {@link #applyMembership}, using {@code householdSizes} so the
840	     * household-of-three-or-more factor reflects the household as it now stands. When the owner
841	     * has no household, or is the only member of its household, no cap applies and the level is
842	     * returned unchanged.
843	     *
844	     * @param ownerDto       the newly created owner's dto, with its uncapped membership already applied
845	     * @param owner          the newly created owner (already saved, so it has an id)
846	     * @param householdSizes household id to member count, as returned by {@link #householdSizes()}
847	     * @return the resulting (possibly capped) membership level
848	     */
849	    private int capMembershipLevelToHousehold(OwnerDto ownerDto, Owner owner,
850	        Map<String, Integer> householdSizes) {
851	        int level = ownerDto.getMembershipLevel();
852	        String householdId = owner.getHouseholdId();
853	        if (householdId == null) {
854	            return level;
855	        }
856	        Integer maxMemberLevel = null;
857	        for (Owner existing : this.clinicService.findAllOwners()) {
858	            if (existing.isDeleted() || existing.getId().equals(owner.getId())) {
859	                continue;
860	            }
861	            if (householdId.equals(existing.getHouseholdId())) {
862	                int size = householdSizes.getOrDefault(householdId, 1);
863	                int memberLevel = MembershipPoints.level(MembershipPoints.points(existing, size));
864	                maxMemberLevel = maxMemberLevel == null ? memberLevel
865	                    : Math.max(maxMemberLevel, memberLevel);
866	            }
867	        }
868	        if (maxMemberLevel != null && level > maxMemberLevel + 1) {
869	            level = maxMemberLevel + 1;
870	            ownerDto.setMembershipLevel(level);
871	        }
872	        return level;
873	    }
