875	    /**
876	     * Counts how many owners belong to each household, keyed by household id. Owners without a
877	     * household id (no postcode) are excluded — such an owner is its own single-member household.
878	     *
879	     * @return a map from household id to the number of owners sharing it
880	     */
881	    private Map<String, Integer> householdSizes() {
882	        Map<String, Integer> sizes = new java.util.HashMap<>();
883	        for (Owner existing : this.clinicService.findAllOwners()) {
884	            String householdId = existing.getHouseholdId();
885	            if (householdId != null) {
886	                sizes.merge(householdId, 1, Integer::sum);
887	            }
888	        }
889	        return sizes;
890	    }
