892	    /**
893	     * Applies soft-match (possible-duplicate) detection to a new owner that has already
894	     * cleared hard {@code identityKey} duplicate rejection. The owner is flagged as a
895	     * possible duplicate when a non-deleted existing owner shares its {@link
896	     * OwnerIdentity#soundex soundex(lastName)} and its postcode while producing a different
897	     * {@code identityKey}; {@code possibleDuplicateOf} is then set to that existing owner's id.
898	     * Because the telephone is part of the identity key, two owners with the same last name and
899	     * postcode but different telephones differ in their keys and so surface here as a soft match
900	     * rather than a hard duplicate. When several existing owners match, the one with the lowest
901	     * id is chosen so the result is deterministic. When no such owner exists — or the new owner
902	     * has no postcode to compare — {@code possibleDuplicate} is set to {@code false} and no
903	     * matching id is recorded.
904	     *
905	     * @param owner the new owner, already normalized (E.164 telephone, validated postcode)
906	     */
907	    private void applyPossibleDuplicate(Owner owner) {
908	        owner.setPossibleDuplicate(false);
909	        if (owner.getPostcode() == null) {
910	            return;
911	        }
912	        String soundex = OwnerIdentity.soundex(owner.getLastName());
913	        String identityKey = OwnerIdentity.identityKey(owner.getTelephone(), owner.getEmail(), owner.getLastName());
914	        Owner match = null;
915	        for (Owner existing : this.clinicService.findAllOwners()) {
916	            if (existing.isDeleted()) {
917	                continue;
918	            }
919	            if (soundex.equals(OwnerIdentity.soundex(existing.getLastName()))
920	                && owner.getPostcode().equals(existing.getPostcode())
921	                && !identityKey.equals(OwnerIdentity.identityKey(toE164(existing.getTelephone()),
922	                    existing.getEmail(), existing.getLastName()))) {
923	                if (match == null || (existing.getId() != null
924	                    && existing.getId() < match.getId())) {
925	                    match = existing;
926	                }
927	            }
928	        }
929	        if (match != null) {
930	            owner.setPossibleDuplicate(true);
931	            owner.setPossibleDuplicateOf(match.getId());
932	        }
933	    }
