935	    /**
936	     * Normalizes a telephone number for owner creation into E.164 form. Spaces, dashes
937	     * and brackets are stripped. When the number already carries a leading {@code '+'}
938	     * and country code these are kept; a number written in national trunk form (a leading
939	     * {@code '0'}) is treated as Australian, so the {@code '0'} is dropped and country code
940	     * {@code '+61'} prepended; any other bare number is treated as a NANP number and country
941	     * code {@code '+1'} is prepended. The resulting number must have between 8 and 15 digits
942	     * after the {@code '+'}, and its national-number length must be valid for the detected
943	     * country code (see {@link #hasValidNationalLength}).
944	     *
945	     * @param telephone the raw telephone value supplied by the client
946	     * @return the E.164 telephone (e.g. {@code +61412345678}), or {@code null} when it
947	     *         cannot form a valid E.164 number (signalling a 400 Bad Request)
948	     */
949	    private static String toE164(String telephone) {
950	        if (telephone == null) {
951	            return null;
952	        }
953	        String cleaned = telephone.replaceAll("[\\s\\-()]", "");
954	        String digits;
955	        if (cleaned.startsWith("+")) {
956	            digits = cleaned.substring(1);
957	        } else if (cleaned.startsWith("0")) {
958	            digits = "61" + cleaned.substring(1);
959	        } else {
960	            digits = "1" + cleaned;
961	        }
962	        if (!digits.matches("[0-9]{8,15}")) {
963	            return null;
964	        }
965	        if (!hasValidNationalLength(digits)) {
966	            return null;
967	        }
968	        return "+" + digits;
969	    }
970	
971	    /**
972	     * Validates the national-number length of an E.164 digit string against its country
973	     * code: Australia ({@code +61}) requires exactly 9 national digits and the NANP
974	     * ({@code +1}) requires exactly 10. Numbers under any other country code are not
975	     * length-checked here — only the general 8-to-15-digit E.164 bound applies to them.
976	     *
977	     * @param digits the E.164 digits (without the leading {@code '+'})
978	     * @return {@code true} when the national-number length is valid for the country code
979	     */
980	    private static boolean hasValidNationalLength(String digits) {
981	        if (digits.startsWith("61")) {
982	            return digits.length() - 2 == 9;
983	        }
984	        if (digits.startsWith("1")) {
985	            return digits.length() - 1 == 10;
986	        }
987	        return true;
988	    }
