990	    /**
991	     * Inclusive 4-digit postcode ranges permitted for each canonical region: NSW 2000-2099,
992	     * VIC 3000-3099 and QLD 4000-4099. A region absent from this table (e.g. the {@code
993	     * "UNKNOWN"} derived for a city with no known region) imposes no range restriction.
994	     */
995	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
996	        "NSW", new int[] {2000, 2099},
997	        "VIC", new int[] {3000, 3099},
998	        "QLD", new int[] {4000, 4099});
999	
1000	    /**
1001	     * Validates an owner's postcode for creation. A postcode is only ever validated when
1002	     * present (an absent postcode is optional and accepted). When present it must be exactly
1003	     * four digits and, for a city whose {@link OwnerLocality#forCity region} has a known
1004	     * postcode range, must fall inside that inclusive range (NSW 2000-2099, VIC 3000-3099,
1005	     * QLD 4000-4099). A city with no known region accepts any 4-digit postcode.
1006	     *
1007	     * @param postcode the supplied postcode (never {@code null} here)
1008	     * @param city     the owner's city, used to derive the region
1009	     * @return {@code true} when the postcode is valid for the city, {@code false} otherwise
1010	     *         (signalling a 400 Bad Request)
1011	     */
1012	    private static boolean isValidPostcode(String postcode, String city) {
1013	        if (!postcode.matches("[0-9]{4}")) {
1014	            return false;
1015	        }
1016	        int[] range = REGION_POSTCODES.get(
1017	            org.springframework.samples.petclinic.mapper.OwnerLocality.forCity(city));
1018	        if (range == null) {
1019	            return true;
1020	        }
1021	        int value = Integer.parseInt(postcode);
1022	        return value >= range[0] && value <= range[1];
1023	    }
