40	
41	/**
42	 * Global Exception handler for REST controllers.
43	 * <p>
44	 * This class handles exceptions thrown by REST controllers and returns appropriate HTTP responses to the client.
45	 *
46	 * @author Vitaliy Fedoriv
47	 * @author Alexander Dudkin
48	 */
49	@ControllerAdvice
50	public class ExceptionControllerAdvice {
51	
52	    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
53	    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
54	    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
55	    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";
56	
57	    /**
58	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
59	     * class.
60	     *
61	     * @param e     Object referring to the thrown exception.
62	     * @param status HTTP response status.
63	     * @param url URL request.
64	     */
65	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
66	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
67	        problemDetail.setType(URI.create(url.toString()));
68	        problemDetail.setTitle(e.getClass().getSimpleName());
69	        problemDetail.setDetail(detail);
70	        problemDetail.setProperty("timestamp", Instant.now());
71	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
72	        problemDetail.setProperty("errors", List.<String>of());
73	        return problemDetail;
74	    }
75	
76	    /**
77	     * Re-throws {@link AccessDeniedException} so Spring Security's {@code ExceptionTranslationFilter}
78	     * translates it as it normally would - 403 for an authenticated user lacking the required role,
79	     * or the configured entry point for an anonymous one. Without this, {@link #handleGeneralException}
80	     * would catch it and report an authorization failure as a 500.
81	     *
82	     * @param e The {@link AccessDeniedException} to propagate
83	     * @throws AccessDeniedException always
84	     */
85	    @ExceptionHandler(AccessDeniedException.class)
86	    public void handleAccessDeniedException(AccessDeniedException e) throws AccessDeniedException {
87	        throw e;
88	    }
89	
90	    /**
91	     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
92	     *
93	     * @param e The {@link Exception} to be handled
94	     * @param request {@link HttpServletRequest} object referring to the current request.
95	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
96	     */
97	    @ExceptionHandler(Exception.class)
98	    @ResponseBody
99	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
100	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
101	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
102	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
103	        return ResponseEntity.status(status).body(detail);
104	    }
105	
106	    /**
107	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
108	     * method returns a 404 Not Found status if an entity does not exist.
109	     *
110	     * @param e The {@link DataIntegrityViolationException} to be handled
111	     * @param request {@link HttpServletRequest} object referring to the current request.
112	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
113	     */
114	    @ExceptionHandler(DataIntegrityViolationException.class)
115	    @ResponseBody
116	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
117	        logger.warn("Data integrity violation at {} {}: {}",
118	            request.getMethod(),
119	            request.getRequestURI(),
120	            e.getMessage());
121	        logger.debug("Data integrity violation stacktrace", e);
122	        HttpStatus status = HttpStatus.NOT_FOUND;
123	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
124	        return ResponseEntity.status(status).body(detail);
125	    }
126	
127	    /**
128	     * Handles {@link BadRequestException} raised when a request is malformed or violates a
129	     * business rule. Returns a 400 Bad Request as an RFC 7807 {@code application/problem+json}
130	     * response.
131	     *
132	     * @param e The {@link BadRequestException} to be handled
133	     * @param request {@link HttpServletRequest} object referring to the current request.
134	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status
135	     */
136	    @ExceptionHandler(BadRequestException.class)
137	    @ResponseBody
138	    public ResponseEntity<ProblemDetail> handleBadRequestException(BadRequestException e, HttpServletRequest request) {
139	        HttpStatus status = HttpStatus.BAD_REQUEST;
140	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), e.getMessage());
141	        return ResponseEntity.status(status).body(detail);
142	    }
143	
144	    /**
145	     * Handles {@link ConflictException} raised when a request conflicts with the current state of
146	     * the resource. Returns a 409 Conflict as an RFC 7807 {@code application/problem+json}
147	     * response.
148	     *
149	     * @param e The {@link ConflictException} to be handled
150	     * @param request {@link HttpServletRequest} object referring to the current request.
151	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status
152	     */
153	    @ExceptionHandler(ConflictException.class)
154	    @ResponseBody
155	    public ResponseEntity<ProblemDetail> handleConflictException(ConflictException e, HttpServletRequest request) {
156	        HttpStatus status = HttpStatus.CONFLICT;
157	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), e.getMessage());
158	        return ResponseEntity.status(status).body(detail);
159	    }
160	
161	    /**
162	     * Handles {@link RateLimitExceededException} raised when a rate limit has been exceeded.
163	     * Returns a 429 Too Many Requests as an RFC 7807 {@code application/problem+json} response.
164	     *
165	     * @param e The {@link RateLimitExceededException} to be handled
166	     * @param request {@link HttpServletRequest} object referring to the current request.
167	     * @return A {@link ResponseEntity} containing the error information and a 429 Too Many Requests status
168	     */
169	    @ExceptionHandler(RateLimitExceededException.class)
170	    @ResponseBody
171	    public ResponseEntity<ProblemDetail> handleRateLimitExceededException(RateLimitExceededException e, HttpServletRequest request) {
172	        HttpStatus status = HttpStatus.TOO_MANY_REQUESTS;
173	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), e.getMessage());
174	        return ResponseEntity.status(status).body(detail);
175	    }
176	
177	    /**
178	     * Handles exception thrown by Bean Validation on controller methods parameters
179	     *
180	     * @param e The {@link MethodArgumentNotValidException} to be handled
181	     * @param request {@link HttpServletRequest} object referring to the current request.
182	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
183	     */
184	    @ExceptionHandler(MethodArgumentNotValidException.class)
185	    @ResponseBody
186	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
187	        HttpStatus status = HttpStatus.BAD_REQUEST;
188	        BindingErrorsResponse errors = new BindingErrorsResponse();
189	        BindingResult bindingResult = e.getBindingResult();
190	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
191	        if (bindingResult.hasErrors()) {
192	            errors.addAllErrors(bindingResult);
193	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
194	                .map(fieldError -> {
195	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
196	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
197	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
198	                        fieldError.getField(),
199	                        defaultMessage,
200	                        rejectedValue);
201	                    return new ValidationMessageDto(message)
202	                        .putAdditionalProperty("field", fieldError.getField())
203	                        .putAdditionalProperty("rejectedValue", rejectedValue)
204	                        .putAdditionalProperty("defaultMessage", defaultMessage);
205	                })
206	                .toList();
207	            List<String> errorFields = bindingResult.getFieldErrors().stream()
208	                .map(FieldError::getField)
209	                .distinct()
210	                .toList();
211	            logger.debug("Validation error at {} {}: {}",
212	                request.getMethod(),
213	                request.getRequestURI(),
214	                bindingResult.getFieldErrors());
215	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
216	            detail.setProperty("errors", errorFields);
217	            return ResponseEntity.status(status).body(detail);
218	        }
219	        return ResponseEntity.status(status).body(detail);
220	    }
221	
222	}
